-- These SECURITY DEFINER helpers are used internally by RLS policies.
-- Keep them executable by the table owner/postgres and service_role,
-- but prevent direct RPC execution by anonymous or authenticated API users.
REVOKE ALL ON FUNCTION public.can_edit_customer(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.can_view_customer(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.customer_owner(uuid) FROM PUBLIC;

REVOKE EXECUTE ON FUNCTION public.can_edit_customer(uuid) FROM anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.can_view_customer(uuid) FROM anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.customer_owner(uuid) FROM anon, authenticated;

GRANT EXECUTE ON FUNCTION public.can_edit_customer(uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.can_view_customer(uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.customer_owner(uuid) TO service_role;

CREATE INDEX IF NOT EXISTS customer_shares_granted_by_idx ON public.customer_shares (granted_by);
CREATE INDEX IF NOT EXISTS drawings_user_id_idx ON public.drawings (user_id);
CREATE INDEX IF NOT EXISTS photos_user_id_idx ON public.photos (user_id);

ALTER POLICY "owner manages fields" ON public.custom_fields
USING (user_id = (select auth.uid()))
WITH CHECK (user_id = (select auth.uid()));

ALTER POLICY "owner creates shares" ON public.customer_shares
WITH CHECK ((customer_owner(customer_id) = (select auth.uid())) AND (granted_by = (select auth.uid())) AND (recipient_user_id <> (select auth.uid())));

ALTER POLICY "owner or recipient reads shares" ON public.customer_shares
USING ((customer_owner(customer_id) = (select auth.uid())) OR (recipient_user_id = (select auth.uid())));

ALTER POLICY "owner revokes shares" ON public.customer_shares
USING (customer_owner(customer_id) = (select auth.uid()));

ALTER POLICY "owner updates shares" ON public.customer_shares
USING (customer_owner(customer_id) = (select auth.uid()))
WITH CHECK (customer_owner(customer_id) = (select auth.uid()));

ALTER POLICY "insert own customers" ON public.customers
WITH CHECK (user_id = (select auth.uid()));

ALTER POLICY "owner deletes customers" ON public.customers
USING (user_id = (select auth.uid()));

ALTER POLICY "view own or shared customers" ON public.customers
USING ((user_id = (select auth.uid())) OR can_view_customer(id));

ALTER POLICY "add drawings to editable customers" ON public.drawings
